// Controller stays thin: validate, authorise, delegate
public function store(
    StoreCampaignRequest $request,
    LaunchCampaign $launch,
): CampaignResource {
    $this->authorize('create', Campaign::class);

    $campaign = $launch(
        $request->user()->account,
        $request->validated(),
    );

    return new CampaignResource($campaign);
}

// Server state with TanStack Query: caching,
// loading and error handled for you
function CampaignStats({ id }: { id: number }) {
  const { data, isPending, error } = useQuery({
    queryKey: ['campaign-stats', id],
    queryFn: ({ signal }) =>
      api.get<Stat[]>(`/campaigns/${id}/stats`,
                      { signal }),
    staleTime: 60_000,
  })

  if (isPending) return <Spinner />
  if (error) return <ErrorPanel error={error} />
  if (!data.length) return <Empty />
  return <StatsChart stats={data} />
}

// Search box: debounce, skip repeats,
// cancel stale requests
results$ = this.query.valueChanges.pipe(
  debounceTime(300),
  distinctUntilChanged(),
  switchMap(q => this.api.searchCandidates(q)),
);
